def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay the given settings on the defaults mode="fast" and level="3".

    keys[i] is set to values[i]. Returns the resulting values in this order:
    the value of "mode", the value of "level", then the values of any other
    keys in the order they first appear in `keys`. If a key repeats, the
    last value given for it wins. The function is pure and uses no
    external resources.

    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    result: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        result[k] = v
    return list(result.values())


import pytest


def test_defaults_when_empty() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode() -> None:
    assert settings(["mode"], ["slow"]) == ["slow", "3"]


def test_override_level() -> None:
    assert settings(["level"], ["7"]) == ["fast", "7"]


def test_override_both_any_order() -> None:
    assert settings(["level", "mode"], ["1", "safe"]) == ["safe", "1"]


def test_extra_keys_in_given_order() -> None:
    assert settings(["zeta", "alpha"], ["z", "a"]) == ["fast", "3", "z", "a"]


def test_extras_mixed_with_overrides() -> None:
    keys = ["x", "level", "y", "mode"]
    values = ["1", "9", "2", "turbo"]
    assert settings(keys, values) == ["turbo", "9", "1", "2"]


def test_duplicate_key_last_wins() -> None:
    assert settings(["mode", "mode"], ["a", "b"]) == ["b", "3"]


def test_duplicate_extra_key_keeps_first_position() -> None:
    keys = ["x", "y", "x"]
    values = ["1", "2", "3"]
    assert settings(keys, values) == ["fast", "3", "3", "2"]


def test_empty_string_value() -> None:
    assert settings(["mode"], [""]) == ["", "3"]


def test_inputs_not_mutated() -> None:
    keys = ["a", "mode"]
    values = ["1", "slow"]
    settings(keys, values)
    assert keys == ["a", "mode"]
    assert values == ["1", "slow"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["a", "b"], ["1"])
    with pytest.raises(ValueError):
        settings(["a"], ["1", "2"])
